previewCss:
.darma-loader-darma-b12-honeycomb-fill { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 100px); height: calc(var(--loader-size, 100px) * .96); position: relative; }
.darma-loader-darma-b12-honeycomb-fill span { position: absolute; width: 34%; height: 30%; clip-path: polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%); background: var(--accent); animation: darma-loader-darma-b12-honeycomb-fill-comb calc(var(--loader-speed, 1s) * 1.9) ease-in-out infinite; }
.darma-loader-darma-b12-honeycomb-fill span:nth-child(1) { left: 33%; top: 35%; background: var(--accent-2); animation-delay: 0s; }
.darma-loader-darma-b12-honeycomb-fill span:nth-child(2) { left: 33%; top: 5%; animation-delay: calc(var(--loader-speed, 1s) * .16); }
.darma-loader-darma-b12-honeycomb-fill span:nth-child(3) { left: 58%; top: 20%; animation-delay: calc(var(--loader-speed, 1s) * .32); }
.darma-loader-darma-b12-honeycomb-fill span:nth-child(4) { left: 58%; top: 50%; animation-delay: calc(var(--loader-speed, 1s) * .48); }
.darma-loader-darma-b12-honeycomb-fill span:nth-child(5) { left: 33%; top: 65%; animation-delay: calc(var(--loader-speed, 1s) * .64); }
.darma-loader-darma-b12-honeycomb-fill span:nth-child(6) { left: 8%; top: 50%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b12-honeycomb-fill span:nth-child(7) { left: 8%; top: 20%; animation-delay: calc(var(--loader-speed, 1s) * .96); }
@keyframes darma-loader-darma-b12-honeycomb-fill-comb { 0%, 100% { opacity: .16; transform: scale(.84); } 45% { opacity: 1; transform: scale(1); } }

